    <div class="col-md-2">
      <label class="form-label small">Required Date</label>
      <input type="date" class="form-control" placeholder="Enter Description" v-model="date" >
    </div>
    <div class="col-md-8">
      <label class="form-label small">Description</label>
      <input type="text" class="form-control" placeholder="Enter Description" v-model="description" >
    </div>

  </div>

  <!-- Add Item Toggle Button -->
  <div class="d-flex justify-content-end me-4 mt-2">
