                :options= "itemLists"
                placeholder="select item"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
    </div>

    <div class="col-md-3">
      <label class="form-label small">Description</label>
      <input type="text" class="form-control" placeholder="Enter Description" v-model="item_description">
