            :columns="itemsColumns"
            :options="table_option"
          >
            <template #actions="props">
              <a href="javascript:void(0);" title="Delete" @click="pullActivity(props.row.Sno)">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20"
                  fill="currentColor" class="bi bi-trash text-danger" viewBox="0 0 16 16">
                  <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                  <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1z"/>
                </svg>
              </a>
            </template>
          </v-client-table>
        </div>
      </div>
    </div>

  </div>
</div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary"  @click="resetForm()" >Close</button>
          <button type="submit" class="btn btn-primary" :disable = "isSending">
            <span v-if="isSending" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Submit
          </button>
        </div>
      </form>
             <!-- item registration form ends-->



              <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="conversion" :columns="columns" :options="table_option">
                            <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openRequestModal(props.row); getStores();" data-bs-toggle="modal" :data-bs-target="'#site-material-modal'">
                                    <i class="bi bi-eye text-primary fs-3"></i>
                                </a>

                                 <a 
  href="javascript:void(0);" class="text-dark position-relative ms-2" @click="openRequestModal(props.row); getLogs();" data-bs-target="#note-modal" data-bs-toggle="modal"> 
   <i class="bi bi-journal-bookmark-fill text-secondary  fs-4"></i>
    <span 
    v-if="props.row.request_logs > 0"
    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
    style="font-size: 9px; min-width: 16px; padding: 2px 4px;"
  >
    {{ props.row.request_logs }}
  </span>
</a>
                            </template>
                            <template #status="props">
                                <span class="badge inv-status" :class="'badge-' + props.row.status.color">{{ props.row.status.name }} </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

<div class="modal fade mymodal" id="site-material-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editConversionFactorModalLabel">{{ material_request?.project }} MATERIAL REQUESTS</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" ></button>
      </div>
        <div class="modal-body">
    <!-- Header info -->
<div class="panel p-0">
    <div class="table-responsive mb-3">
        <table class="table table-bordered table-sm">
            <tbody>
                <tr>
                    <th width="20%">Project</th>
                    <td>{{ material_request?.project }}</td>

                    <th width="20%">Required Date</th>
                    <td>{{ material_request?.required_date }}</td>
                </tr>

                <tr>
                    <th>Requested By</th>
                    <td colspan="3">
                        {{ material_request?.requester }}
                    </td>
                </tr>

                <tr>
                    <th>Description</th>
                    <td colspan="3">
                        {{ material_request?.description }}
                    </td>
                </tr>

                <!-- Notes button -->
                <tr>
                    <th>Notes:</th>
                    <td colspan="3">
                        <a
                            href="javascript:void(0);"
                            class="text-dark position-relative ms-2"
                            @click.stop="openNoteModal()"
                        >
                            <i class="bi bi-journal-bookmark-fill text-secondary fs-4"></i>

                                                <span 
    v-if="material_request.request_logs > 0"
    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
    style="font-size: 9px; min-width: 16px; padding: 2px 4px;"
  >
    {{ material_request.request_logs }}
  </span>
                        </a>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>

    <hr/>

         <!-- Send Button and Select Store on the same row -->
        <div class="d-flex justify-content-between align-items-center mb-3" v-if ="user_permissions.includes('can_issue_site_material_requests') && material_request.status_id != 32">
          <!-- Send Button - Left Side -->
           <div class="col-md-6 col-lg-4">
            <label class="form-label small">Select Store</label>
            <multiselect 
                v-model="store"
                :options="stores"
                placeholder="Select Store"
                label="name"
                :searchable="true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
          </div>
         

          <!-- Select Store - Right Side -->
           <div>
            <button type="button" @click="sendIssueRequisition()" class="btn btn-success py-2 px-2">
                  <span v-if="isSending" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
          <span v-else>         <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" class="bi bi-send" viewBox="0 0 16 16">
  <path d="M15.854.146a.5.5 0 0 1 .11.54l-5.819 14.547a.75.75 0 0 1-1.329.124l-3.178-4.995L.643 7.184a.75.75 0 0 1 .124-1.33L15.314.037a.5.5 0 0 1 .54.11ZM6.636 10.07l2.761 4.338L14.13 2.576zm6.787-8.201L1.591 6.602l4.339 2.76z"/>
</svg>
</span>
     
            </button>
          </div>
        </div>

        
    <!-- Items Table -->
   <!-- Items Table -->
<div class="panel p-0">
    <div class="custom-table table3">
        <table class="table table-bordered table-striped">
            <thead>
                <tr>
                    <th>SNo</th>
                    <th>Item</th>
                    <th>Description</th>
                    <th>Quantity</th>
                    <th v-if="store">Store Item</th>
                    <th v-if="store">Qty Issuing</th>
                    <th v-if="store">Condition</th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="(item, index) in modalRequestItems" :key="index">
                    <td>{{ index + 1 }}</td>
                    <td>{{ item.item }}</td>
                    <td>{{ item.description }}</td>
                    <td>{{ item.quantity }}</td>
                    <td v-if="store">
                        <multiselect
                            v-model="item.store_item"
                            :options="storeItems"
                            placeholder="Select Item"
                            label="name"
                            :searchable="true"
                            :multiple="false"
                            :allow-empty="false"
                            @select="item.issued_quantity = ''"
                        ></multiselect>
                    </td>
                    <td v-if="store">
                        <input
                            v-if="item.store_item"
                            type="number"
                            class="form-control"
                            :placeholder="'Available: ' + (item.store_item?.balance_quantity ?? 0)"
                            v-model.number="item.issued_quantity"
                            :max="Math.min(item.store_item.balance_quantity, parseFloat(item.quantity))"
                            :min="0.1"
                            step="any"
                            @input="item.issued_quantity = Math.min(item.issued_quantity, item.store_item.balance_quantity, parseFloat(item.quantity))"
                        />
                        <span v-else class="text-muted small">Select item first</span>
                    </td>
                    <td v-if="store">
                        <span class="form-control">
                            {{ item.store_item?.condition ?? 'Select item first' }}
                        </span>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>
</div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" >Close</button>
        </div>
    </div>
  </div>
</div>


<div class="modal fade mymodal" id="note-modal" data-bs-backdrop="false" 
     data-bs-keyboard="false" tabindex="-1" aria-hidden="true">
  <div class="modal-dialog modal-lg modal-dialog-centered">
    <div class="modal-content" style="border-radius:20px;max-height:80vh;display:flex;flex-direction:column;">

      <!-- Header -->
      <div class="modal-header" style="padding:14px 18px;border-bottom:0.5px solid #dee2e6;">
        <span style="font-size:15px;font-weight:500;">Notes for Site Materila Requests No. {{ material_request.id }} </span>
        <button type="button" v-if="user_permissions.includes('can_request_order_cancellation') && item?.status?.name === 'approved'" class="btn btn-warning ms-auto" @click="cancellation_request =! cancellation_request" :disabled="sending">
          <span v-if="sending" v-html="loadingSpinner()"></span>
          <span v-else>Request Cancellation</span>
          </button>
        <button type="button" class="btn-close ms-auto" data-bs-dismiss="modal"></button>
      </div>

      <!-- Body / Feed -->
      <div class="modal-body" style="overflow-y:auto;flex:1;padding:16px 18px;">

        <div v-if="logsLoading" class="text-center py-4">
          <span v-html="waitIndicator()"></span>
        </div>

        <div v-else-if="logs.length === 0" class="text-center text-muted py-5">
          <svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" fill="currentColor" 
               class="bi bi-chat-square-dots mb-2 d-block mx-auto" viewBox="0 0 16 16">
            <path d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1h-2.5a2 2 0 0 0-1.6.8L8 14.333 
                     6.1 11.8a2 2 0 0 0-1.6-.8H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1z"/>
          </svg>
          No notes yet for Site Material Requests No. {{ material_request.id }}
        </div>

        <!-- Comment thread -->
        <div v-else class="d-flex flex-column gap-4">
